(function(){const $=id=>document.getElementById(id);let verified={email:false,phone:false};
 $('verify-email').onclick=()=>{if(!$('reg-email').value)return alert('Enter an email first.');verified.email=true;$('verify-email').textContent='Email verified ✓';};
 $('verify-phone').onclick=()=>{if(!$('reg-phone').value)return alert('Enter a phone number first.');verified.phone=true;$('verify-phone').textContent='Phone verified ✓';};
 function baseUsername(){const email=$('reg-email').value.trim().toLowerCase(), phone=$('reg-phone').value.replace(/\D/g,'');return email?email.split('@')[0].replace(/[^a-z0-9._-]/g,''):('user'+phone.slice(-6));}
 $('register-form').addEventListener('submit',e=>{e.preventDefault();const email=$('reg-email').value.trim().toLowerCase(),phone=$('reg-phone').value.trim(),custom=$('reg-username').value.trim().toLowerCase();if(!verified.email&&!verified.phone){$('register-result').textContent='Verify the email or phone number before creating the account.';return;}const username=(custom||baseUsername()).replace(/[^a-z0-9._-]/g,'');const taken=(window.SRU_PORTAL.users||[]).some(u=>u.username===username);if(taken){$('register-result').textContent='That username is already taken. Choose another.';return;}const user={id:'U'+Date.now(),username,email,phone,role:'User',status:'active',provider:'local',verified:'yes'};const pending=JSON.parse(localStorage.getItem('sru_pending_users')||'[]');pending.push(user);localStorage.setItem('sru_pending_users',JSON.stringify(pending));$('register-result').textContent='Account created in prototype mode as '+username+'. An admin should approve/assign a role in production.';});})();
